using System;using System.IO;using System.Text.Json;using Microsoft.CodeAnalysis;using Microsoft.CodeAnalysis.CSharp;
public static class FixtureDriver {
 public static void Main(){string line;while((line=Console.ReadLine())!=null){try{using(var doc=JsonDocument.Parse(line)){var j=doc.RootElement;string source=j.GetProperty("source").GetString();var tree=CSharpSyntaxTree.ParseText(source);var refs=new[]{MetadataReference.CreateFromFile(typeof(object).Assembly.Location),MetadataReference.CreateFromFile(typeof(System.Runtime.GCSettings).Assembly.Location)};var comp=CSharpCompilation.Create("SourceOnlyFixture",new[]{tree},refs,new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));var result=Round9ScopedExitCandidates.Generate(source,tree.GetRoot(),comp.GetSemanticModel(tree),j.GetProperty("point").GetInt32(),j.GetProperty("family").GetString(),j.GetProperty("original_transfer_opcode").GetString(),j.GetProperty("join_kind").GetString(),j.TryGetProperty("join_source_point",out var p)?p.GetInt32():-1);Console.WriteLine(JsonSerializer.Serialize(new{patches=result,source_only=true,game_compile=false}));}}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{error=e.GetType().Name,message=e.Message}));}}}
}
